    /// Build a one-date-field index whose `ts` field carries `precision`.
    async fn date_index(
        engine: &crate::Engine,
        name: &str,
        precision: Option<xerj_common::types::DatePrecision>,
        docs: &[(&str, &str)],
    ) -> std::sync::Arc<crate::Index> {
        let mut ts = FieldConfig::new("ts", FieldType::Date);
        ts.options.date_precision = precision;
        let mut schema = Schema::empty();
        schema.add_field(ts).unwrap();
        engine.create_index(name, schema).unwrap();
        let idx = engine.get_index(name).unwrap();
        idx.abort_background_tasks();
        for (id, v) in docs {
            idx.index_document(Some((*id).into()), json!({ "ts": v }))
                .await
                .unwrap();
        }
        idx
    }

    async fn sort_ids(idx: &std::sync::Arc<crate::Index>, order: &str) -> Vec<String> {
        let req = xerj_query::parse_request(
            &json!({"query": {"match_all": {}}, "size": 10, "sort": [{"ts": order}]}),
        )
        .unwrap();
        idx.search(&req)
            .await
            .unwrap()
            .hits
            .iter()
            .map(|h| h.id.clone())
            .collect()
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn date_mixed_precision_sorts_and_ranges_consistently() {
        // #790: the sort-shadow, the per-hit sort keys and a range's bounds all
        // guessed a date's epoch scale from the VALUE — >= 4 fractional-second
        // digits meant nanoseconds, anything coarser meant milliseconds. A
        // `date` column mixing the two therefore held keys six orders of
        // magnitude apart: doc `s` (2020, sub-millisecond) got ~1.59e18 while
        // doc `w` (2025, whole-second) got ~1.75e12, so `s` sorted LAST despite
        // being the earlier instant, and a millisecond-scale range bound could
        // not reach it. With the scale resolved from the MAPPING (an ES `date`
        // is millisecond-precision), one column is one scale and both agree.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        // true chronological order: e(2019) < s(2020, sub-ms) < w(2025).
        let idx = date_index(
            &engine,
            "date-mixed",
            Some(xerj_common::types::DatePrecision::Millis),
            &[
                ("w", "2025-01-01T00:00:00Z"),
                ("s", "2020-06-06T06:06:06.123456Z"),
                ("e", "2019-01-01T00:00:00Z"),
            ],
        )
        .await;
        let range_count = |idx: std::sync::Arc<crate::Index>, body: serde_json::Value| async move {
            let req = xerj_query::parse_request(
                &json!({"query": body, "size": 10, "track_total_hits": true}),
            )
            .unwrap();
            let r = idx.search(&req).await.unwrap();
            let mut ids: Vec<_> = r.hits.iter().map(|h| h.id.clone()).collect();
            ids.sort();
            (r.total.value, ids)
        };
        for phase in ["pre-flush", "post-flush"] {
            assert_eq!(
                sort_ids(&idx, "asc").await,
                vec!["e".to_string(), "s".to_string(), "w".to_string()],
                "#790 {phase}: a mixed-precision date column must sort by instant"
            );
            assert_eq!(
                sort_ids(&idx, "desc").await,
                vec!["w".to_string(), "s".to_string(), "e".to_string()],
                "#790 {phase}: desc must be the exact reverse"
            );
            // The reported symptom: a range whose bound is the sub-millisecond
            // doc's OWN stored value returned the doc before flush and nothing
            // after it, because the ms bound sat 6 orders of magnitude below
            // the nanosecond shadow key the segment had built.
            assert_eq!(
                range_count(
                    idx.clone(),
                    json!({"range": {"ts": {"gte": "2020-06-06T06:06:06.123456Z",
                                           "lte": "2020-06-06T06:06:06.123456Z"}}})
                )
                .await,
                (1u64, vec!["s".to_string()]),
                "#790 {phase}: a range on the sub-ms doc's own value must find it"
            );
            assert_eq!(
                range_count(idx.clone(), json!({"range": {"ts": {"gte": "2021-01-01"}}})).await,
                (1u64, vec!["w".to_string()]),
                "#790 {phase}: gte 2021 keeps only w"
            );
            assert_eq!(
                range_count(idx.clone(), json!({"range": {"ts": {"lt": "2021-01-01"}}})).await,
                (2u64, vec!["e".to_string(), "s".to_string()]),
                "#790 {phase}: lt 2021 keeps e and s"
            );
            if phase == "pre-flush" {
                idx.flush().await.unwrap();
                assert_eq!(idx.memtable.doc_count(), 0);
            }
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn date_nanos_field_keeps_nanosecond_sort_values() {
        // The guard on the #790 fix. XERJ maps BOTH `date` and `date_nanos`
        // onto `FieldType::Date`, and before the `date_precision` flag the
        // per-VALUE guess was the only thing giving a `date_nanos` field its
        // nanosecond sort values (`search/240_date_nanos.yml` asserts them
        // exactly). Narrowing every date to milliseconds is what sank the
        // first attempt at this fix (PR #791), so a field the mapping declares
        // `date_nanos` must keep the guess — and therefore its nanosecond
        // keys — before AND after flush.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let idx = date_index(
            &engine,
            "date-ns",
            Some(xerj_common::types::DatePrecision::Nanos),
            &[
                ("first", "2018-10-29T12:12:12.123456789Z"),
                ("second", "2018-10-29T12:12:12.987654321Z"),
            ],
        )
        .await;
        let sort_values = |idx: std::sync::Arc<crate::Index>| async move {
            let req = xerj_query::parse_request(
                &json!({"query": {"match_all": {}}, "size": 10, "sort": [{"ts": "asc"}]}),
            )
            .unwrap();
            idx.search(&req)
                .await
                .unwrap()
                .hits
                .iter()
                .map(|h| (h.id.clone(), h.sort.clone()))
                .collect::<Vec<_>>()
        };
        for phase in ["pre-flush", "post-flush"] {
            assert_eq!(
                sort_values(idx.clone()).await,
                vec![
                    ("first".to_string(), vec![json!(1540815132123456789i64)]),
                    ("second".to_string(), vec![json!(1540815132987654321i64)]),
                ],
                "#790 {phase}: a date_nanos field must keep nanosecond sort values"
            );
            if phase == "pre-flush" {
                idx.flush().await.unwrap();
                assert_eq!(idx.memtable.doc_count(), 0);
            }
        }
    }

    #[test]
    fn date_scale_follows_the_declared_mapping() {
        // The whole point of #790: the scale is a property of the FIELD.
        use xerj_common::types::DatePrecision;
        let mut schema = Schema::empty();
        // The native API means ES `date` — `FieldConfig::new` pins it.
        schema
            .add_field(FieldConfig::new("plain", FieldType::Date))
            .unwrap();
        let mut ns = FieldConfig::new("ns", FieldType::Date);
        ns.options.date_precision = Some(DatePrecision::Nanos);
        schema.add_field(ns).unwrap();
        // A mapping written before the flag existed: no silent change of scale.
        let mut legacy = FieldConfig::new("legacy", FieldType::Date);
        legacy.options.date_precision = None;
        schema.add_field(legacy).unwrap();
        schema
            .add_field(FieldConfig::new("word", FieldType::Keyword))
            .unwrap();
        let scale = |name: &str| {
            declared_field(&schema, name)
                .map(date_scale_of_config)
                .unwrap_or(DateScale::PerValue)
        };
        assert_eq!(scale("plain"), DateScale::Millis);
        assert_eq!(scale("ns"), DateScale::PerValue);
        assert_eq!(scale("legacy"), DateScale::PerValue);
        assert_eq!(scale("word"), DateScale::PerValue);
        assert_eq!(scale("undeclared"), DateScale::PerValue);
        assert_eq!(
            millis_date_fields(&schema),
            ["plain".to_string()].into_iter().collect()
        );
        // A millisecond field truncates sub-millisecond digits; the per-value
        // scale keeps them, which is the whole ms-vs-ns split.
        let sub = "2020-06-06T06:06:06.123456Z";
        assert_eq!(
            date_string_to_epoch(sub, DateScale::Millis),
            Some(json!(1591423566123i64))
        );
        assert_eq!(
            date_string_to_epoch(sub, DateScale::PerValue),
            Some(json!(1591423566123456000i64))
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn date_term_normalizes_formats_and_epoch_ms_across_flush() {
        // #788: a `term` on a date field must match by instant, not by raw
        // stored representation. "2020-01-01", "2020-01-01T00:00:00Z", and the
        // epoch-ms number 1577836800000 all name the same instant as doc `a`,
        // so all three must return [a] — before AND after flush (the segment
        // path must agree with the memtable source scan; no new divergence).
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("ts", FieldType::Date))
            .unwrap();
        engine.create_index("date-term", schema).unwrap();
        let idx = engine.get_index("date-term").unwrap();
        idx.abort_background_tasks();
        for (id, ts) in [
            ("a", "2020-01-01T00:00:00Z"),
            ("b", "2021-06-15T00:00:00Z"),
            ("c", "2022-12-31T00:00:00Z"),
            // Sub-millisecond precision (>=4 fractional digits): the sort-shadow
            // stores this in nanoseconds, so a ms-scale range would miss it.
            ("d", "2020-03-03T03:03:03.123456Z"),
        ] {
            idx.index_document(Some(id.into()), json!({ "ts": ts }))
                .await
                .unwrap();
        }
        let run = |idx: std::sync::Arc<crate::Index>, body: serde_json::Value| async move {
            let req = xerj_query::parse_request(&json!({
                "query": body, "size": 10, "track_total_hits": true
            }))
            .unwrap();
            let r = idx.search(&req).await.unwrap();
            let mut ids: Vec<_> = r.hits.iter().map(|h| h.id.clone()).collect();
            ids.sort();
            (r.total.value, ids)
        };
        let shapes: Vec<serde_json::Value> = vec![
            json!({"term": {"ts": "2020-01-01T00:00:00Z"}}),
            json!({"term": {"ts": "2020-01-01"}}),
            json!({"term": {"ts": 1577836800000i64}}),
        ];
        let count0 = |idx: std::sync::Arc<crate::Index>, body: serde_json::Value| async move {
            let req = xerj_query::parse_request(&json!({
                "query": body, "size": 0, "track_total_hits": true
            }))
            .unwrap();
            idx.search(&req).await.unwrap().total.value
        };
        let want = (1u64, vec!["a".to_string()]);
        // A sub-millisecond term must still match its own exact stored value
        // after flush (#789: the ms-scale range rewrite lost these to the
        // nanosecond sort-shadow — the rewrite must be skipped for such values).
        let subms = json!({"term": {"ts": "2020-03-03T03:03:03.123456Z"}});
        let want_d = (1u64, vec!["d".to_string()]);
        for phase in ["pre-flush", "post-flush"] {
            for body in &shapes {
                let got = run(idx.clone(), body.clone()).await;
                assert_eq!(got, want, "#788 {phase} {body} must match doc a by instant");
                // size:0 count fast path must agree with the hit scan.
                let c = count0(idx.clone(), body.clone()).await;
                assert_eq!(c, 1, "#788 {phase} {body} size:0 count must be 1");
            }
            let got_d = run(idx.clone(), subms.clone()).await;
            assert_eq!(
                got_d, want_d,
                "#789 {phase} exact sub-ms term must match doc d"
            );
            let c_d = count0(idx.clone(), subms.clone()).await;
            assert_eq!(
                c_d, 1,
                "#789 {phase} exact sub-ms term size:0 count must be 1"
            );
            if phase == "pre-flush" {
                idx.flush().await.unwrap();
                assert_eq!(idx.memtable.doc_count(), 0);
            }
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn flush_increments_the_bytes_written_metric() {
        // #804: `xerj_bytes_written_total` was registered but nothing ever
        // incremented it, so it stayed 0 regardless of write volume. The
        // handle is a process-wide `OnceLock` (set-once) and MORE THAN ONE
        // test installs one (`bytes_written_metric_increments_on_flush`), so
        // whichever runs first wins the race and a locally-constructed
        // `Metrics` may never be the one `engine_metrics()` (and thus flush)
        // increments — reading it gave a flat 0 under high-core parallelism.
        // Read the INSTALLED handle instead, and assert `after > before`
        // rather than an exact delta since concurrent flushes share it.
        crate::set_engine_metrics(std::sync::Arc::new(
            xerj_common::metrics::Metrics::new().unwrap(),
        ));
        let metrics = crate::engine_metrics().expect("engine metrics installed");
        let before = metrics.bytes_written.get();

        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine
            .create_index("bytes-written", Schema::empty())
            .unwrap();
        let idx = engine.get_index("bytes-written").unwrap();
        idx.abort_background_tasks();
        idx.index_document(Some("a".into()), json!({ "f": "x" }))
            .await
            .unwrap();
        idx.flush().await.unwrap();

        let after = metrics.bytes_written.get();
        assert!(
            after > before,
            "#804 a flush must increment xerj_bytes_written_total: before={before} after={after}"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn schemaless_cidr_term_matches_the_subnet_after_flush() {
        // #786: a CIDR `term` on an undeclared (dynamically mapped) ip-shaped
        // field matches in the memtable (the value-driven source scan expands
        // it via `ip_matches_cidr`) but returned 0 once the docs flushed to a
        // segment — the #782/#413 flush-divergence: same query, different
        // results before and after flush. The declared-ip rewrite (#783) can't
        // cover this: dynamic mapping never infers `ip`, so its `FieldType::Ip`
        // guard is false. Post-flush must AGREE with the memtable.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine
            .create_index("schemaless-cidr", Schema::empty())
            .unwrap();
        let idx = engine.get_index("schemaless-cidr").unwrap();
        idx.abort_background_tasks();
        for (id, addr) in [
            ("a", "192.168.1.5"),
            ("b", "192.168.1.200"),
            ("c", "10.0.0.1"),
            ("d", "192.168.2.5"),
        ] {
            idx.index_document(Some(id.into()), json!({ "addr": addr }))
                .await
                .unwrap();
        }
        let cidr = xerj_query::parse_request(&json!({
            "query": {"term": {"addr": "192.168.1.0/24"}},
            "size": 10,
            "track_total_hits": true
        }))
        .unwrap();

        // Memtable: the source scan matches the two 192.168.1.x docs.
        let pre = idx.search(&cidr).await.unwrap();
        let mut pre_ids: Vec<_> = pre.hits.iter().map(|h| h.id.clone()).collect();
        pre_ids.sort();
        assert_eq!(
            pre_ids,
            vec!["a".to_string(), "b".to_string()],
            "memtable CIDR term must match the /24 subnet"
        );
        assert_eq!(pre.total.value, 2, "memtable CIDR count must be the subnet");

        idx.flush().await.unwrap();
        // Memtable drained, so the query now resolves against the segment(s).
        assert_eq!(idx.memtable.doc_count(), 0);
        assert!(!idx.store.snapshot().segments.is_empty());

        // Post-flush must agree with the memtable (was 0 before the #786 fix).
        let post = idx.search(&cidr).await.unwrap();
        let mut post_ids: Vec<_> = post.hits.iter().map(|h| h.id.clone()).collect();
        post_ids.sort();
        assert_eq!(
            post_ids,
            vec!["a".to_string(), "b".to_string()],
            "#786: schemaless CIDR term must still match the /24 subnet after flush"
        );
        assert_eq!(
            post.total.value, 2,
            "#786: post-flush CIDR count must agree with the memtable"
        );

        // Count-only (size:0) exercises the `seg_term_positions` shortcut, which
        // had the same ord-only miss as the prefilter builder.
        let count_only = xerj_query::parse_request(&json!({
            "query": {"term": {"addr": "192.168.1.0/24"}},
            "size": 0,
            "track_total_hits": true
        }))
        .unwrap();
        let counted = idx.search(&count_only).await.unwrap();
        assert_eq!(
            counted.total.value, 2,
            "#786: post-flush size:0 CIDR count must be the subnet"
        );

        // A CIDR term wrapped in a `bool.filter` exercises the segment
        // bool-count shortcuts, which had the same ord-only miss.
        for size in [0, 10] {
            let boolq = xerj_query::parse_request(&json!({
                "query": {"bool": {"filter": [{"term": {"addr": "192.168.1.0/24"}}]}},
                "size": size,
                "track_total_hits": true
            }))
            .unwrap();
            let r = idx.search(&boolq).await.unwrap();
            assert_eq!(
                r.total.value, 2,
                "#786: post-flush bool.filter CIDR count must be the subnet (size {size})"
            );
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn exists_requires_a_non_null_value_across_flush() {
        // ES `exists` matches a field iff it has >=1 non-null value. An explicit
        // null, `[]`, and `[null]` do NOT match; `[null,"x"]` does. XERJ matched
        // by key-presence (wrong). Must hold for schemaless AND declared fields,
        // via size:10 hits AND size:0 count, before and after flush.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("kw", FieldType::Keyword))
            .unwrap();
        engine.create_index("exists-nn", schema).unwrap();
        let idx = engine.get_index("exists-nn").unwrap();
        idx.abort_background_tasks();
        // Each doc sets BOTH a schemaless `f` and a declared keyword `kw` to the
        // same shape, so both field kinds are exercised identically.
        let docs = vec![
            ("present", json!("x")),
            ("null", Value::Null),
            ("empty_arr", json!([])),
            ("null_arr", json!([null])),
            ("mixed_arr", json!(["a", null])),
        ];
        for (id, v) in &docs {
            idx.index_document(Some((*id).into()), json!({ "f": v, "kw": v }))
                .await
                .unwrap();
        }
        // "missing" sets neither field.
        idx.index_document(Some("missing".into()), json!({ "other": 1 }))
            .await
            .unwrap();
        let want = vec!["mixed_arr".to_string(), "present".to_string()];
        let ex = |idx: std::sync::Arc<crate::Index>, field: &'static str, size: u64| async move {
            let req = xerj_query::parse_request(&json!({
                "query": {"exists": {"field": field}}, "size": size, "track_total_hits": true
            }))
            .unwrap();
            let r = idx.search(&req).await.unwrap();
            let mut ids: Vec<_> = r.hits.iter().map(|h| h.id.clone()).collect();
            ids.sort();
            (r.total.value, ids)
        };
        for phase in ["pre", "post"] {
            for field in ["f", "kw"] {
                let (total, ids) = ex(idx.clone(), field, 10).await;
                assert_eq!(
                    ids, want,
                    "{phase} exists on {field}: only non-null values match"
                );
                assert_eq!(total, 2, "{phase} exists on {field} count must be 2");
                let (c0, _) = ex(idx.clone(), field, 0).await;
                assert_eq!(c0, 2, "{phase} exists on {field} size:0 count must be 2");
            }
            if phase == "pre" {
                idx.flush().await.unwrap();
                assert_eq!(idx.memtable.doc_count(), 0);
            }
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn partial_update_deep_merges_nested_objects() {
        // #821: a partial `_update` of a field INSIDE a nested object must keep
        // the object's other fields (ES recursive deep-merge), not shallow-
        // replace the whole object (which dropped siblings = data-loss).
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine.create_index("upd821", Schema::empty()).unwrap();
        let idx = engine.get_index("upd821").unwrap();
        idx.abort_background_tasks();
        idx.index_document(
            Some("1".into()),
            json!({
                "author": {"name": "amy", "id": 7, "addr": {"city": "NYC", "zip": "10001"}},
                "title": "x",
                "tags": ["a", "b"],
            }),
        )
        .await
        .unwrap();
        // Patch: rename author.name, deepen author.addr.city, replace tags, add top-level.
        idx.update_document_with_upsert(
            "1",
            Some(json!({
                "author": {"name": "bob", "addr": {"city": "LA"}},
                "tags": ["c"],
                "extra": 1,
            })),
            None,
            false,
        )
        .await
        .unwrap();
        let got = idx.get_document("1").await.unwrap().unwrap();
        // Nested siblings preserved: author.id, author.addr.zip.
        assert_eq!(
            got["author"]["id"],
            json!(7),
            "author.id must survive: {got}"
        );
        assert_eq!(
            got["author"]["name"],
            json!("bob"),
            "author.name updated: {got}"
        );
        assert_eq!(
            got["author"]["addr"]["zip"],
            json!("10001"),
            "addr.zip must survive: {got}"
        );
        assert_eq!(
            got["author"]["addr"]["city"],
            json!("LA"),
            "addr.city updated: {got}"
        );
        // Top-level scalar unchanged; array REPLACED (not merged, ES semantics); new key added.
        assert_eq!(got["title"], json!("x"), "title survives: {got}");
        assert_eq!(
            got["tags"],
            json!(["c"]),
            "array replaced, not merged: {got}"
        );
        assert_eq!(got["extra"], json!(1), "new top-level key added: {got}");
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn multivalue_sort_reduces_min_for_asc_max_for_desc() {
        // A multi-valued numeric field must rank by each doc's MIN value for an
        // ascending sort and MAX for a descending one (ES default), with an
        // explicit `mode` overriding that. Before the fix, `compute_sort_values`
        // handed the raw array to the comparator, which fell through to
        // `stringify-and-compare` — ranking docs by the JSON text of the array.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine.create_index("mvs", Schema::empty()).unwrap();
        let idx = engine.get_index("mvs").unwrap();
        idx.abort_background_tasks();
        // mins:  A=1  C=5  B=40      maxes: C=100 B=50 A=10
        idx.index_document(Some("A".into()), json!({"vals": [10, 1]}))
            .await
            .unwrap();
        idx.index_document(Some("B".into()), json!({"vals": [40, 50]}))
            .await
            .unwrap();
        idx.index_document(Some("C".into()), json!({"vals": [5, 100]}))
            .await
            .unwrap();
        // A single-element array must sort numerically, not lexically:
        // string compare put "[10]" before "[9]".
        idx.index_document(Some("nine".into()), json!({"v1": [9]}))
            .await
            .unwrap();
        idx.index_document(Some("ten".into()), json!({"v1": [10]}))
            .await
            .unwrap();
        let order = |idx: std::sync::Arc<crate::Index>, body: serde_json::Value| async move {
            let req = xerj_query::parse_request(&body).unwrap();
            let r = idx.search(&req).await.unwrap();
            r.hits.iter().map(|h| h.id.clone()).collect::<Vec<_>>()
        };
        let asc = json!({"query":{"exists":{"field":"vals"}},"size":10,"sort":[{"vals":{"order":"asc"}}]});
        let desc = json!({"query":{"exists":{"field":"vals"}},"size":10,"sort":[{"vals":{"order":"desc"}}]});
        let asc_max = json!({"query":{"exists":{"field":"vals"}},"size":10,"sort":[{"vals":{"order":"asc","mode":"max"}}]});
        let single =
            json!({"query":{"exists":{"field":"v1"}},"size":10,"sort":[{"v1":{"order":"asc"}}]});
        let check = |idx: &std::sync::Arc<crate::Index>| {
            let idx = idx.clone();
            let (asc, desc, asc_max, single) =
                (asc.clone(), desc.clone(), asc_max.clone(), single.clone());
            async move {
                // asc -> by min: A(1) C(5) B(40)
                assert_eq!(order(idx.clone(), asc).await, vec!["A", "C", "B"]);
                // desc -> by max: C(100) B(50) A(10)
                assert_eq!(order(idx.clone(), desc).await, vec!["C", "B", "A"]);
                // explicit mode:max overrides the asc default: A(10) B(50) C(100)
                assert_eq!(order(idx.clone(), asc_max).await, vec!["A", "B", "C"]);
                // single-element arrays sort numerically: 9 before 10
                assert_eq!(order(idx.clone(), single).await, vec!["nine", "ten"]);
            }
        };
        check(&idx).await;
        idx.flush().await.unwrap();
        check(&idx).await;
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn match_minimum_should_match_requires_k_terms() {
        // #832: a `match` with `minimum_should_match` was dropped — the
        // OR-over-tokens BM25 path ignored it, so `match {msm:2}` behaved as OR
        // and returned docs matching only ONE term. Fix routes match-with-msm
        // to the doc-scan path (like operator:and), which enforces the count.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine.create_index("msm", Schema::empty()).unwrap();
        let idx = engine.get_index("msm").unwrap();
        idx.abort_background_tasks();
        idx.index_document(Some("both".into()), json!({"t": "quick brown fox"}))
            .await
            .unwrap();
        idx.index_document(Some("one".into()), json!({"t": "quick red car"}))
            .await
            .unwrap();
        let run = |idx: std::sync::Arc<crate::Index>, q: serde_json::Value| async move {
            let req = xerj_query::parse_request(
                &json!({"query":{"match":{"t":q}},"size":10,"track_total_hits":true}),
            )
            .unwrap();
            let r = idx.search(&req).await.unwrap();
            let mut ids: Vec<_> = r.hits.iter().map(|h| h.id.clone()).collect();
            ids.sort();
            (r.total.value, ids)
        };
        for phase in ["mem", "seg"] {
            assert_eq!(
                run(idx.clone(), json!("quick brown")).await,
                (2, vec!["both".to_string(), "one".to_string()]),
                "OR default ({phase})"
            );
            assert_eq!(
                run(
                    idx.clone(),
                    json!({"query":"quick brown","minimum_should_match":2})
                )
                .await,
                (1, vec!["both".to_string()]),
                "msm:2 ({phase})"
            );
            assert_eq!(
                run(
                    idx.clone(),
                    json!({"query":"quick brown","minimum_should_match":"100%"})
                )
                .await,
                (1, vec!["both".to_string()]),
                "msm:100% ({phase})"
            );
            assert_eq!(
                run(
                    idx.clone(),
                    json!({"query":"quick brown","minimum_should_match":1})
                )
                .await,
                (2, vec!["both".to_string(), "one".to_string()]),
                "msm:1 ({phase})"
            );
            if phase == "mem" {
                idx.flush().await.unwrap();
            }
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn terms_agg_include_exclude_is_fully_anchored() {
        // #837: terms include/exclude regex must match the WHOLE term (ES
        // fully-anchored Lucene regexp), not a substring. Before the fix
        // `include:"a.*"` matched every term containing an `a`.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("g", FieldType::Keyword))
            .unwrap();
        engine.create_index("ie837", schema).unwrap();
        let idx = engine.get_index("ie837").unwrap();
        idx.abort_background_tasks();
        for (id, g) in [
            ("1", "apple"),
            ("2", "apricot"),
            ("3", "banana"),
            ("4", "avocado"),
        ] {
            idx.index_document(Some(id.into()), json!({ "g": g }))
                .await
                .unwrap();
        }
        let run = |idx: std::sync::Arc<crate::Index>, terms: serde_json::Value| async move {
            let req = xerj_query::parse_request(
                &json!({"query":{"match_all":{}},"size":0,"aggs":{"byg":{"terms":terms}}}),
            )
            .unwrap();
            let r = idx.search(&req).await.unwrap();
            let mut ks: Vec<String> = r
                .aggs
                .as_ref()
                .and_then(|a| a["byg"]["buckets"].as_array())
                .map(|bs| {
                    bs.iter()
                        .filter_map(|b| b["key"].as_str().map(String::from))
                        .collect()
                })
                .unwrap_or_default();
            ks.sort();
            ks
        };
        for phase in ["mem", "seg"] {
            // include "a.*": only terms STARTING with a (anchored).
            assert_eq!(
                run(idx.clone(), json!({"field":"g","size":10,"include":"a.*"})).await,
                vec!["apple", "apricot", "avocado"],
                "include a.* ({phase})"
            );
            // exclude "a.*": only banana survives.
            assert_eq!(
                run(idx.clone(), json!({"field":"g","size":10,"exclude":"a.*"})).await,
                vec!["banana"],
                "exclude a.* ({phase})"
            );
            // "ppl" is a substring of apple but not the whole term => no bucket.
            assert!(
                run(idx.clone(), json!({"field":"g","size":10,"include":"ppl"}))
                    .await
                    .is_empty(),
                "include ppl must be empty ({phase})"
            );
            if phase == "mem" {
                idx.flush().await.unwrap();
            }
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn terms_agg_numeric_key_order_is_numeric_not_lexicographic() {
        // A terms agg on a numeric field must order `_key` (and break count
        // ties) NUMERICALLY, like ES — not by the lexicographic string form of
        // the number. Before the fix the comparator did `key_a.cmp(&key_b)` on
        // the raw string keys, so [2, 10, 100] sorted as ["10","100","2"], even
        // though the bucket keys are emitted as JSON numbers.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("n", FieldType::Long))
            .unwrap();
        engine.create_index("ntk", schema).unwrap();
        let idx = engine.get_index("ntk").unwrap();
        idx.abort_background_tasks();
        // counts: 10->2, 2->1, 100->1.
        for (id, n) in [("a", 10), ("b", 10), ("c", 2), ("d", 100)] {
            idx.index_document(Some(id.into()), json!({ "n": n }))
                .await
                .unwrap();
        }
        let run = |idx: std::sync::Arc<crate::Index>, order: serde_json::Value| async move {
            let terms = if order.is_null() {
                json!({"field":"n","size":10})
            } else {
                json!({"field":"n","size":10,"order":order})
            };
            let req = xerj_query::parse_request(
                &json!({"query":{"match_all":{}},"size":0,"aggs":{"byn":{"terms":terms}}}),
            )
            .unwrap();
            let r = idx.search(&req).await.unwrap();
            r.aggs
                .as_ref()
                .and_then(|a| a["byn"]["buckets"].as_array())
                .map(|bs| {
                    bs.iter()
                        .filter_map(|b| b["key"].as_i64())
                        .collect::<Vec<i64>>()
                })
                .unwrap_or_default()
        };
        for phase in ["mem", "seg"] {
            // order _key asc: 2 < 10 < 100 numerically (lexically "10" < "2").
            assert_eq!(
                run(idx.clone(), json!({"_key":"asc"})).await,
                vec![2i64, 10, 100],
                "_key asc numeric ({phase})"
            );
            // order _key desc.
            assert_eq!(
                run(idx.clone(), json!({"_key":"desc"})).await,
                vec![100i64, 10, 2],
                "_key desc numeric ({phase})"
            );
            // default order = count desc, then _key ASC numerically: 10 (count
            // 2) first, then 2 before 100 (lexically "100" < "2" would flip it).
            assert_eq!(
                run(idx.clone(), serde_json::Value::Null).await,
                vec![10i64, 2, 100],
                "default tie-break numeric ({phase})"
            );
            if phase == "mem" {
                idx.flush().await.unwrap();
            }
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn mustnot_only_prefix_keeps_nonmatching_docs_after_flush() {
        // #797: a bool with ONLY a must_not (no must/should/filter) containing a
        // prefix/wildcard leaf returns zero hits after flush — the segment
        // planner lets the negative leaf drive candidate generation, so the
        // non-matching docs never enter the set. `term` is unaffected. Base set
        // must be all docs, must_not subtracting only its matches.
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("k", FieldType::Keyword))
            .unwrap();
        engine.create_index("mn797", schema).unwrap();
        let idx = engine.get_index("mn797").unwrap();
        idx.abort_background_tasks();
        // Data is case-fold-invariant for prefix "ap"/"app*": only "apple"
        // starts with it under ANY casing, so the correct answer does not
        // depend on the separate #794 keyword-prefix case-sensitivity fix.
        for (id, k) in [("1", "apple"), ("2", "grape"), ("3", "banana")] {
            idx.index_document(Some(id.into()), json!({ "k": k }))
                .await
                .unwrap();
        }
        let run = |idx: std::sync::Arc<crate::Index>, q: serde_json::Value| async move {
            let req = xerj_query::parse_request(
                &json!({"query": q, "size": 10, "track_total_hits": true}),
            )
            .unwrap();
            let r = idx.search(&req).await.unwrap();
            let mut ids: Vec<_> = r.hits.iter().map(|h| h.id.clone()).collect();
            ids.sort();
            (r.total.value, ids)
        };
        // must_not-ONLY [prefix "ap"] excludes apple(1); grape(2) + banana(3)
        // must remain, pre AND post flush (before the fix, post-flush dropped
        // ALL docs → (0, []) via the pure-negative FTS projection).
        let want = (2u64, vec!["2".to_string(), "3".to_string()]);
        for phase in ["pre", "post"] {
            for q in [
                json!({"bool": {"must_not": [{"prefix": {"k": "ap"}}]}}),
                json!({"bool": {"must_not": [{"wildcard": {"k": "app*"}}]}}),
            ] {
                assert_eq!(
                    run(idx.clone(), q.clone()).await,
                    want,
                    "#797 {phase} {q}: must_not-only prefix/wildcard keeps non-matching docs"
                );
            }
            if phase == "pre" {
                idx.flush().await.unwrap();
                assert_eq!(idx.memtable.doc_count(), 0);
            }
        }
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn funcscore_filter_prefix_on_keyword_is_case_sensitive() {
        // #802 (#423 family): a function_score per-function `filter` was matched
        // with the SCHEMALESS doc_matches_query, so a keyword `prefix` filter
        // case-FOLDED — "Application" wrongly got the weight-5 boost for prefix
        // "ap" (lowercase) it does not start with. Must be case-sensitive: only
        // "apple" is boosted. Flush-invariant (same on memtable + segment).
        let _fault_test = FLUSH_FAULT_TEST_LOCK.lock().await;
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("k", FieldType::Keyword))
            .unwrap();
        engine.create_index("fs802", schema).unwrap();
        let idx = engine.get_index("fs802").unwrap();
        idx.abort_background_tasks();
        for (id, k) in [("1", "apple"), ("2", "Application"), ("3", "banana")] {
            idx.index_document(Some(id.into()), json!({ "k": k }))
                .await
                .unwrap();
        }
        let run = |idx: std::sync::Arc<crate::Index>| async move {
            let q = json!({"function_score": {
                "query": {"match_all": {}},
                "functions": [{"filter": {"prefix": {"k": "ap"}}, "weight": 5.0}],
                "boost_mode": "replace"
            }});
            let req = xerj_query::parse_request(&json!({"query": q, "size": 10})).unwrap();
            let r = idx.search(&req).await.unwrap();
            let mut v: Vec<_> = r.hits.iter().map(|h| (h.id.clone(), h.score)).collect();
            v.sort_by(|a, b| a.0.cmp(&b.0));
            v
        };
        // Only apple(1) starts with lowercase "ap" -> boosted 5.0; Application(2)
        // and banana(3) stay 1.0. (Fold-both would wrongly give (2) a 5.0.)
        let want = vec![
            ("1".to_string(), 5.0f32),
            ("2".to_string(), 1.0f32),
            ("3".to_string(), 1.0f32),
        ];
        for phase in ["pre", "post"] {
            assert_eq!(
                run(idx.clone()).await,
                want,
                "#802 {phase}: function_score keyword prefix filter is case-sensitive"
            );
            if phase == "pre" {
                idx.flush().await.unwrap();
                assert_eq!(idx.memtable.doc_count(), 0);
            }
        }
    }

