    #[tokio::test]
    async fn timed_out_leader_is_not_cached() {
        let dir = TempDir::new().unwrap();
        let engine = engine(&dir);
        engine
            .create_index("cache-timeout", Schema::empty())
            .unwrap();
        let idx = engine.get_index("cache-timeout").unwrap();

        let permits = idx
            .max_concurrent_queries
            .acquire_many(64)
            .await
            .expect("query semaphore");
        let request = match_all(1);
        let timed_out = idx.search(&request).await.unwrap();
        assert!(timed_out.timed_out);
        assert_eq!(
            idx.metric_query_count.load(Ordering::Relaxed),
            1,
            "admission timeout must be included in query metrics"
        );
        assert!(
            idx.query_cache.is_empty(),
            "partial timeout must never enter the result cache"
        );

        drop(permits);
        let completed = idx.search(&request).await.unwrap();
        assert!(!completed.timed_out);
        assert_eq!(idx.query_cache.len(), 1);
        let cached = idx.search(&request).await.unwrap();
        assert!(!cached.timed_out);
        assert_eq!(cached.took_ms, 0);
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 1)]
    async fn cold_vector_segment_load_does_not_block_async_worker() {
        let dir = TempDir::new().unwrap();
        let engine = engine(&dir);
        engine.create_index("cold-vector", Schema::empty()).unwrap();
        let idx = engine.get_index("cold-vector").unwrap();
        idx.index_document(
            Some("v1".into()),
            serde_json::json!({"embedding": [1.0, 0.0]}),
        )
        .await
        .unwrap();
        idx.flush().await.unwrap();
        idx.stored_value_cache.clear();
        idx.test_stored_value_load_delay_ms
            .store(250, Ordering::Relaxed);
        idx.test_stored_value_load_count.store(0, Ordering::Relaxed);

        let mut queries = Vec::new();
        for _ in 0..8 {
            let query_idx = Arc::clone(&idx);
            queries.push(tokio::spawn(async move {
                query_idx
                    .run_knn_brute_force(
                        &match_all(2_000),
                        "embedding",
                        &[1.0, 0.0],
                        1,
                        None,
                        "cosine",
                        None,
                        None,
                    )
                    .await
            }));
        }

        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            while idx.test_stored_value_load_count.load(Ordering::Relaxed) == 0 {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("cold load never reached blocking pool");

        // With one runtime worker this timer cannot complete while a
        // synchronous 250 ms segment load is running on that worker.
        tokio::time::timeout(
            std::time::Duration::from_millis(100),
            tokio::time::sleep(std::time::Duration::from_millis(10)),
        )
        .await
        .expect("cold segment load starved the async runtime worker");

        for query in queries {
            let result = query.await.unwrap().unwrap();
            assert!(!result.timed_out);
            assert_eq!(result.hits.len(), 1);
        }
        assert_eq!(
            idx.test_stored_value_load_count.load(Ordering::Relaxed),
            1,
            "concurrent cold requests must share one parse"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 1)]
    async fn request_deadline_can_drop_cold_vector_load_wait() {
        let dir = TempDir::new().unwrap();
        let engine = engine(&dir);
        engine
            .create_index("cold-deadline", Schema::empty())
            .unwrap();
        let idx = engine.get_index("cold-deadline").unwrap();
        idx.index_document(
            Some("v1".into()),
            serde_json::json!({"embedding": [1.0, 0.0]}),
        )
        .await
        .unwrap();
        idx.flush().await.unwrap();
        idx.stored_value_cache.clear();
        idx.test_stored_value_load_delay_ms
            .store(250, Ordering::Relaxed);

        let started = std::time::Instant::now();
        let result = idx
            .run_knn_brute_force(
                &match_all(20),
                "embedding",
                &[1.0, 0.0],
                1,
                Some(Box::new(QueryNode::MatchAll)),
                "cosine",
                None,
                None,
            )
            .await
            .unwrap();
        assert!(result.timed_out);
        assert_eq!(result.total.relation, TotalHitsRelation::Gte);
        assert!(
            started.elapsed() < std::time::Duration::from_millis(150),
            "request waited for detached cold load instead of its deadline"
        );

        // The detached decode is deliberately not cancelled: the immutable
        // load completes and warms the cache for a later request.
        tokio::time::timeout(std::time::Duration::from_secs(1), async {
            while idx.stored_value_cache.is_empty() {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("detached load did not warm the cache");
    }

    #[tokio::test]
    async fn retired_segment_cannot_be_reinserted_by_detached_load() {
        let dir = TempDir::new().unwrap();
        let engine = engine(&dir);
        engine
            .create_index("retired-load", Schema::empty())
            .unwrap();
        let idx = engine.get_index("retired-load").unwrap();
        idx.index_document(Some("v1".into()), serde_json::json!({"value": 1}))
            .await
            .unwrap();
        idx.flush().await.unwrap();
        let old_meta = idx.store.snapshot().segments[0].clone();
        idx.stored_value_cache.clear();
        idx.test_stored_value_load_pause_before_publish
            .store(true, Ordering::Release);
        idx.test_stored_value_load_ready_to_publish
            .store(false, Ordering::Release);

        let load_idx = Arc::clone(&idx);
        let old_id = old_meta.id.clone();
        let load = tokio::spawn(async move { load_idx.stored_values_for_async(&old_id).await });
        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            while !idx
                .test_stored_value_load_ready_to_publish
                .load(Ordering::Acquire)
            {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("cold load did not reach publication gate");

        // Publish a replacement exactly as merge does, then perform the
        // stored-value eviction while holding the lifecycle write guard.
        let mut replacement = old_meta.clone();
        replacement.id = Uuid::new_v4().to_string();
        replacement.seg_path = format!("segments/{}.seg", replacement.id);
        replacement.sidx_path = format!("segments/{}.sidx", replacement.id);
        idx.store
            .apply_merge(std::slice::from_ref(&old_meta.id), replacement)
            .unwrap();
        {
            let _publication = idx.segment_cache_lifecycle.write();
            idx.stored_value_cache.remove(&old_meta.id);
        }
        idx.test_stored_value_load_pause_before_publish
            .store(false, Ordering::Release);

        assert!(
            load.await.unwrap().is_some(),
            "old-snapshot caller should receive the completed immutable load"
        );
        assert!(
            !idx.stored_value_cache.contains_key(&old_meta.id),
            "detached completion resurrected a retired segment"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn all_hydration_publishers_refuse_retired_segment_resurrection() {
        let dir = TempDir::new().unwrap();
        let engine = engine(&dir);
        engine
            .create_index("all-cache-retire", Schema::empty())
            .unwrap();
        let idx = engine.get_index("all-cache-retire").unwrap();
        idx.index_document(Some("v1".into()), serde_json::json!({"value": 1}))
            .await
            .unwrap();
        idx.flush().await.unwrap();
        let old_meta = idx.store.snapshot().segments[0].clone();
        {
            let _publication = idx.segment_cache_lifecycle.write();
            idx.remove_segment_hydration_entries(&old_meta.id);
        }

        // Derived, not hard-coded: a new SegmentCacheCategory must widen this
        // mask automatically or the test silently stops covering it.
        let all = (1_u64 << CATEGORY_COUNT) - 1;
        idx.test_segment_cache_publish_ready_mask
            .store(0, Ordering::Release);
        idx.test_segment_cache_publish_pause_mask
            .store(all, Ordering::Release);

        let mut publishers = Vec::new();
        for category in SegmentCacheCategory::ALL {
            let idx = Arc::clone(&idx);
            let old_id = old_meta.id.clone();
            publishers.push(std::thread::spawn(move || match category {
                SegmentCacheCategory::StoredSlices => {
                    let key = old_id.clone();
                    let _ = idx.publish_current(
                        &idx.stored_slices_cache,
                        &old_id,
                        key,
                        category,
                        1,
                        StoredSlices {
                            bytes: vec![b'{', b'}'],
                            offsets: vec![(0, 2)],
                        },
                    );
                }
                SegmentCacheCategory::DocValues => {
                    let key = old_id.clone();
                    let _ = idx.publish_current(
                        &idx.dv_cache,
                        &old_id,
                        key,
                        category,
                        1,
                        DocValueMap::new(),
                    );
                }
                SegmentCacheCategory::StoredValues => {
                    let key = old_id.clone();
                    let _ = idx.publish_current(
                        &idx.stored_value_cache,
                        &old_id,
                        key,
                        category,
                        1,
                        vec![serde_json::json!({"_id": "v1"})],
                    );
                }
                SegmentCacheCategory::SortShadow => {
                    let key = format!("{old_id}\u{1}field");
                    let _ = idx.publish_current(
                        &idx.sort_shadow_cache,
                        &old_id,
                        key,
                        category,
                        1,
                        Some(Arc::new(vec![(1, 0)])),
                    );
                }
                SegmentCacheCategory::IdPositions => {
                    let key = old_id.clone();
                    let _ = idx.publish_current(
                        &idx.id_pos_cache,
                        &old_id,
                        key,
                        category,
                        1,
                        std::collections::HashMap::from([(String::from("v1"), 0)]),
                    );
                }
                SegmentCacheCategory::RowSequences => {
                    let key = old_id.clone();
                    let _ =
                        idx.publish_current(&idx.row_seq_cache, &old_id, key, category, 1, vec![1]);
                }
                SegmentCacheCategory::DecodedStored => {
                    let key = old_id.clone();
                    let _ = idx.publish_current(
                        &idx.decoded_stored_cache,
                        &old_id,
                        key,
                        category,
                        1,
                        vec![b'{', b'}'],
                    );
                }
                SegmentCacheCategory::FtsReader => {
                    // Open with an empty field set: the reader is then cheap to
                    // build and holds nothing, but it exercises the same
                    // publish/evict path as a real one, which is what this test
                    // is about. `open` on a flushed segment cannot fail here.
                    let key = format!("{old_id}\u{1}");
                    let reader = FtsIndexReader::open(
                        idx.data_dir.join("segments"),
                        old_id.clone(),
                        &[] as &[&str],
                    )
                    .expect("opening a flushed segment with no fields must succeed");
                    let _ = idx.publish_current(
                        &idx.fts_reader_cache,
                        &old_id,
                        key,
                        category,
                        1,
                        Arc::new(reader),
                    );
                }
            }));
        }

        tokio::time::timeout(std::time::Duration::from_secs(2), async {
            while idx
                .test_segment_cache_publish_ready_mask
                .load(Ordering::Acquire)
                != all
            {
                tokio::task::yield_now().await;
            }
        })
        .await
        .expect("all publishers did not reach the deterministic gate");

        let mut replacement = old_meta.clone();
        replacement.id = Uuid::new_v4().to_string();
        replacement.seg_path = format!("segments/{}.seg", replacement.id);
        replacement.sidx_path = format!("segments/{}.sidx", replacement.id);
        idx.store
            .apply_merge(std::slice::from_ref(&old_meta.id), replacement)
            .unwrap();
        {
            let _publication = idx.segment_cache_lifecycle.write();
            idx.remove_segment_hydration_entries(&old_meta.id);
        }
        idx.test_segment_cache_publish_pause_mask
            .store(0, Ordering::Release);
        for publisher in publishers {
            publisher.join().unwrap();
        }

        assert!(!idx.stored_slices_cache.contains_key(&old_meta.id));
        assert!(!idx.dv_cache.contains_key(&old_meta.id));
        assert!(!idx.stored_value_cache.contains_key(&old_meta.id));
        assert!(!idx.id_pos_cache.contains_key(&old_meta.id));
        assert!(!idx.row_seq_cache.contains_key(&old_meta.id));
        assert!(!idx.decoded_stored_cache.contains_key(&old_meta.id));
        let prefix = format!("{}\u{1}", old_meta.id);
        assert!(!idx
            .sort_shadow_cache
            .iter()
            .any(|entry| entry.key().starts_with(&prefix)));
    }

