        assert!(!idx.stored_slices_cache.contains_key(&segment_id));
        assert!(!idx.dv_cache.contains_key(&segment_id));
        assert!(!idx.stored_value_cache.contains_key(&segment_id));
        assert!(!idx.id_pos_cache.contains_key(&segment_id));
