// Graph expansion (second brain) — batched, columnar, bounded
// ─────────────────────────────────────────────────────────────────────────────
// Declared as a CHILD of this module (via `#[path]`) rather than a sibling:
// the hop path needs `dv_columns_for`, `ghost_positions_for`, `self.store`,
// `self.memtable`, `self.data_dir` — all private to `index`. A child module
// sees them without widening any visibility; the implementation still lives in
// its own file (src/graph.rs) instead of growing this one.
#[path = "graph.rs"]
pub mod graph;

// Child module (same `#[path]` reason as `graph`): the WAL-shard override
// helpers are private free functions of this module.
#[cfg(test)]
#[path = "wal_shard_settings_tests.rs"]
mod wal_shard_settings_tests;

#[cfg(test)]
mod unwrap_single_clause_643_wrapper_tests {
    use super::*;
    use xerj_query::ast::{BoolOperator, MinShouldMatch, QueryNode};

    fn bare_match() -> QueryNode {
        QueryNode::Match {
            field: "body".into(),
            query: "x".into(),
            operator: BoolOperator::Or,
            analyzer: None,
            boost: None,
            minimum_should_match: None,
        }
    }

    fn single_clause_bool() -> QueryNode {
        QueryNode::Bool {
            must: vec![bare_match()],
            should: vec![],
            must_not: vec![],
            filter: vec![],
            minimum_should_match: None,
        }
    }

    /// A `bool` whose only clause is a lone `should` with the given
    /// `minimum_should_match` — the shape #643 gap 1 is about.
    fn single_should_bool(msm: Option<MinShouldMatch>) -> QueryNode {
        QueryNode::Bool {
            must: vec![],
            should: vec![bare_match()],
            must_not: vec![],
            filter: vec![],
            minimum_should_match: msm,
        }
    }

    /// #643: `unwrap_single_clause_bool` must recurse through `function_score`'s
    /// inner query (a score-preserving wrapper), erasing the nested one-clause
    /// bool to the bare clause.
    #[test]
    fn unwrap_recurses_through_function_score() {
        let q = QueryNode::FunctionScore {
            query: Box::new(single_clause_bool()),
            functions: vec![],
            score_mode: Default::default(),
            boost_mode: Default::default(),
            max_boost: None,
        };
        match unwrap_single_clause_bool(q) {
            QueryNode::FunctionScore { query, .. } => assert!(
                matches!(*query, QueryNode::Match { .. }),
                "the single-clause bool inside function_score must be erased to \
                 the bare clause, got {:?}",
                query
            ),
            other => panic!("function_score wrapper must be preserved, got {:?}", other),
        }
    }

    /// #643: same for every disjunct of a `dis_max`.
    #[test]
    fn unwrap_recurses_through_dis_max() {
        let q = QueryNode::DisMax {
            queries: vec![single_clause_bool()],
            tie_breaker: 0.0,
        };
        match unwrap_single_clause_bool(q) {
            QueryNode::DisMax { queries, .. } => {
                assert_eq!(queries.len(), 1);
                assert!(
                    matches!(queries[0], QueryNode::Match { .. }),
                    "the single-clause bool inside dis_max must be erased, got {:?}",
                    queries[0]
                );
            }
            other => panic!("dis_max wrapper must be preserved, got {:?}", other),
        }
    }

    /// #643 (gap 1): a lone `should` whose `minimum_should_match` is a
    /// `Percentage` that resolves to 1 is the clause-required shape Lucene
    /// collapses to the bare clause, so it must unwrap exactly like
    /// `Fixed(1)`/`None`. msm resolution is `max(1, floor(len * pct / 100))`,
    /// so for the single clause (`len == 1`) every `pct < 200` resolves to 1
    /// (`floor(1 * 199 / 100) == 1`, `max(1, 0) == 1` at `pct == 0`).
    #[test]
    fn unwrap_collapses_lone_should_with_percentage_msm_resolving_to_one() {
        for pct in [0u32, 1, 50, 100, 150, 199] {
            let unwrapped = unwrap_single_clause_bool(single_should_bool(Some(
                MinShouldMatch::Percentage(pct),
            )));
            assert!(
                matches!(unwrapped, QueryNode::Match { .. }),
                "a lone should with {pct}% msm resolves to 1 required and must erase \
                 to the bare clause, got {unwrapped:?}",
            );
        }
    }

    /// #643 (gap 1): a `Percentage` that resolves to >= 2 (`pct >= 200`, since
    /// `floor(1 * 200 / 100) == 2`) requires 2 of the single clause — the bool
    /// matches NOTHING, unlike the bare clause — so it must stay wrapped
    /// (strictly conservative). The parser puts no upper cap on `pct`, so
    /// `"200%"` is reachable.
    #[test]
    fn unwrap_keeps_lone_should_wrapped_when_percentage_msm_exceeds_the_clause_count() {
        for pct in [200u32, 250, 400] {
            let unwrapped = unwrap_single_clause_bool(single_should_bool(Some(
                MinShouldMatch::Percentage(pct),
            )));
            assert!(
                matches!(unwrapped, QueryNode::Bool { .. }),
                "a lone should with {pct}% msm resolves to >= 2 over 1 clause (matches \
                 nothing) and must stay wrapped, got {unwrapped:?}",
            );
        }
    }

    /// #643 (gap 1): `Field`/`Script` msm resolve only at query time (a per-doc
    /// field value or a script result) and can exceed the clause count, so a
    /// static rewrite cannot prove they resolve to 1 — they stay wrapped,
    /// conservatively (the same `_ => false` fall-through as any un-erasable
    /// shape).
    #[test]
    fn unwrap_keeps_lone_should_wrapped_for_query_time_msm() {
        let field = unwrap_single_clause_bool(single_should_bool(Some(MinShouldMatch::Field(
            "req".into(),
        ))));
        assert!(
            matches!(field, QueryNode::Bool { .. }),
            "a Field msm is unresolvable at rewrite time and must stay wrapped, got {field:?}",
        );
        let script = unwrap_single_clause_bool(single_should_bool(Some(MinShouldMatch::Script {
            source: "params.num_terms".into(),
            params: None,
        })));
        assert!(
            matches!(script, QueryNode::Bool { .. }),
            "a Script msm is unresolvable at rewrite time and must stay wrapped, got {script:?}",
        );
    }
}

#[cfg(test)]
thread_local! {
    /// #577 fail-before instrument: the high-water mark of `all_hits.len()`
    /// reached inside the `residual_gate` per-segment loop.
    pub(crate) static RESIDUAL_HITS_PEAK: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
    /// #892 fail-before instrument: how many segments the search answered
    /// from the inverted index (`fts_handled`) and how many it answered by
    /// parsing their stored section. Which route a request took is invisible
    /// from the response — the hits, the total and the ordering contract are
    /// the same either way — so this is what a test can assert on.
    pub(crate) static SEG_FTS_HANDLED: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
    pub(crate) static SEG_STORED_SCANS: std::cell::Cell<usize> =
        const { std::cell::Cell::new(0) };
}

#[cfg(test)]
mod residual_gate_trim_577_tests {
    use super::*;
    use serde_json::json;

    /// #577: the `residual_gate` pass runs with `fts_cap == usize::MAX`, so a
    /// non-selective non-projectable filter (a numeric `range`) alongside an FTS
    /// scoring clause (`match`) must NOT accumulate O(matches) `Hit`s — it eager-
    /// trims to the page cap. Fail-before: with the trim reverted, the peak is
    /// O(matches) (~N); with the fix it stays ~2·materialisation_limit. Page
    /// and count are unchanged either way.
    #[tokio::test]
    async fn residual_gate_bounds_all_hits_to_the_page_cap() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        engine
            .create_index("residual-577", Schema::empty())
            .unwrap();
        let idx = engine.get_index("residual-577").unwrap();

        const N: usize = 2000;
        for i in 0..N {
            idx.index_document(Some(format!("d{i}")), json!({"body": "alpha beta", "n": i}))
                .await
                .unwrap();
        }
        idx.flush().await.unwrap();

        RESIDUAL_HITS_PEAK.with(|c| c.set(0));
        // bool{ must:[match body:alpha — FTS scoring], filter:[range n>=0 — not
        // FTS-projectable, triggers the residual gate] }; every doc matches both.
        let req = xerj_query::parse_request(&json!({
            "size": 10,
            "query": {"bool": {
                "must": [{"match": {"body": "alpha"}}],
                "filter": [{"range": {"n": {"gte": 0}}}]
            }}
        }))
        .unwrap();
        let res = idx.search(&req).await.unwrap();

        assert_eq!(res.total.value, N as u64, "every doc matches match + range");
        assert_eq!(res.hits.len(), 10, "page returns size:10");
        let peak = RESIDUAL_HITS_PEAK.with(|c| c.get());
        assert!(
            peak > 0,
            "the residual_gate path must have run for this query (peak={peak})"
        );
        // For this size:10/from:0 query over a flushed, memtable-empty index the
        // fast-path re-bind (`materialisation_limit = from + size`) applies, so
        // the cap is 10 and the eager trim fires at > 20, giving a real peak of
        // ~21. The `<= 513` bound below is a deliberately loose ceiling (it also
        // covers the general `(from+size+100).max(256)` cap), still far under the
        // no-trim peak of N = 2000 — the assertion is what discriminates the fix.
        assert!(
            peak <= 513,
            "residual survivors must stay O(page cap), not O(matches): peak={peak} (N={N})"
        );
    }
}

#[cfg(test)]
mod pinned_knn_fts_892_tests {
    use super::*;
    use serde_json::json;

    /// #892: a `knn` clause beside a `query` must be answered from the
    /// INVERTED INDEX, not by parsing every stored document of every segment.
    ///
    /// #825/#879 made this shape CORRECT by pre-executing the vector leg and
    /// splicing its top-k back in as `Constant{score, Ids{[id]}}` pinned
    /// clauses. `Ids` has no FTS projection — `_id` is not a term — so the
    /// projection's `should` loop `?`-aborted, `fts_query` came back `None`,
    /// and every segment fell to `scan_stored_section_into`.
    ///
    /// That route is not merely slow, and this test asserts the part that is
    /// USER-VISIBLE. The stored scan admits documents in STORED-LAYOUT order
    /// and, once `all_hits` reaches `materialisation_limit`, materialises
    /// nothing further — it `continue`s to keep counting, with no score
    /// comparison (see the cap in `scan_stored_section_into`). So on a corpus
    /// with more lexical matches than the page cap, the documents reached by
    /// BOTH halves — the ones the #825 contract scores `query_score +
    /// knn_score` and puts at the top — never enter the page at all if they
    /// sit late in the segment. `hits.total` stays exact; the page is wrong.
    ///
    /// FAIL-BEFORE (watched): with `pinned_probe` forced to `None` in
    /// `search_inner` — the pre-#892 behaviour — the page is 10 lexical-only
    /// documents and the assertion below reports the both-halves documents
    /// missing. `hits.total` is 407 either way.
    #[tokio::test]
    async fn pinned_knn_hybrid_is_answered_from_the_inverted_index() {
        let dir = tempfile::tempdir().unwrap();
        let mut config = Config::default();
        config.server.data_dir = dir.path().to_string_lossy().into_owned();
        let engine = crate::Engine::new(config).unwrap();
        let mut schema = Schema::empty();
        schema
            .add_field(FieldConfig::new("body", FieldType::Text))
            .unwrap();
        let mut vector = FieldConfig::new("v", FieldType::Vector);
        vector.options.dimensions = Some(2);
        schema.add_field(vector).unwrap();
        engine.create_index("hy892", schema).unwrap();
        let idx = engine.get_index("hy892").unwrap();

        // 1200 documents. Every third carries the lexical probe term with
        // IDENTICAL text (same tf, same field length → identical BM25), so
        // 400 lexical matches — comfortably more than the page cap, which is
        // what makes the stored scan's layout-ordered admission observable.
        // Vectors fan from [0,1] to [1,0], so the query vector [1,0] puts the
        // LAST ten (d1190..d1199) in the k=10 neighbourhood; three of those
        // are also lexical matches (1191, 1194, 1197) and must lead the page
        // in vector order, 1197 first.
        const N: usize = 1200;
        for i in 0..N {
            let body = if i % 3 == 0 {
                "alpha filler"
            } else {
                "beta filler"
            };
            let t = i as f32 / N as f32;
            idx.index_document(
                Some(format!("d{i}")),
                json!({ "body": body, "v": [t, 1.0 - t] }),
            )
            .await
            .unwrap();
        }
        idx.flush().await.unwrap();

        SEG_FTS_HANDLED.with(|c| c.set(0));
        SEG_STORED_SCANS.with(|c| c.set(0));
        let req = xerj_query::parse_request(&json!({
            "size": 10,
            "track_total_hits": true,
            "query": {"bool": {"should": [
                {"match": {"body": "alpha"}},
                {"knn": {"field": "v", "query_vector": [1.0, 0.0], "k": 10,
                         "num_candidates": 100}}
            ]}}
        }))
        .unwrap();
        let res = idx.search(&req).await.unwrap();

        // The union: 400 lexical matches ∪ 10 neighbours, overlapping in
        // three documents. Exact on BOTH routes — the page is what differs.
        assert_eq!(
            res.total.value, 407,
            "hits.total must be the UNION of the lexical half (400) and the \
             vector top-10, which share d1191/d1194/d1197: got {:?}",
            res.total
        );

        let page: Vec<(&str, f32)> = res.hits.iter().map(|h| (h.id.as_str(), h.score)).collect();
        let ids: Vec<&str> = page.iter().map(|(id, _)| *id).collect();
        assert_eq!(
            &ids[..3],
            &["d1197", "d1194", "d1191"],
            "#825/#892: the documents reached by BOTH halves score \
             `query_score + knn_score` and must lead the page, ordered by \
             their vector scores — the stored-doc scan drops them because it \
             admits in layout order and stops materialising at the page cap: \
             page={page:?}"
        );
        assert!(
            page[2].1 > page[3].1,
            "the last both-halves document must still outrank the best \
             lexical-only one: {page:?}"
        );

        // And it came from the index, on every segment.
        let fts = SEG_FTS_HANDLED.with(|c| c.get());
        let scans = SEG_STORED_SCANS.with(|c| c.get());
        assert!(
            fts > 0 && scans == 0,
            "the pinned kNN hybrid must be served by the FTS path on every \
             segment: fts={fts} stored_scans={scans}"
        );
    }

    /// The projection arm in isolation: `pin_knn_clause`'s output lifts to a
    /// `DocScores` leaf carrying the resolved positions and the pinned
    /// scores, and the ids the segment does not hold are simply absent.
    #[test]
    fn pinned_sub_tree_projects_to_a_doc_scores_leaf() {
        let pinned = QueryNode::Bool {
            must: Vec::new(),
            should: vec![
                QueryNode::Constant {
                    score: 0.75,
                    query: Box::new(QueryNode::Ids {
                        values: vec!["a".into()],
                    }),
                },
                QueryNode::Constant {
                    score: 0.25,
                    query: Box::new(QueryNode::Ids {
                        values: vec!["elsewhere".into()],
                    }),
                },
            ],
            filter: vec![QueryNode::Ids {
                values: vec!["a".into(), "elsewhere".into()],
            }],
            must_not: Vec::new(),
            minimum_should_match: Some(MinShouldMatch::Fixed(1)),
        };
        let text_fields: Vec<String> = vec!["body".into()];
        let empty: std::collections::HashSet<String> = std::collections::HashSet::new();

        // Without a resolver the projection declines exactly as it did before
        // #892 — `Ids` is not a term.
        assert!(
            query_node_to_fts_projected(&pinned, &text_fields, &empty, &empty, None).is_none(),
            "no resolver ⇒ the pinned sub-tree must still decline"
        );

        let mut positions: std::collections::HashMap<String, u32> =
            std::collections::HashMap::new();
        positions.insert("a".into(), 7);
        let projected = query_node_to_fts_projected(
            &pinned,
            &text_fields,
            &empty,
            &empty,
            Some(PinnedIds::Positions(&positions)),
        )
        .expect("a resolvable pinned sub-tree must project");
        match projected {
            FtsQuery::DocScores(ds) => assert_eq!(
                ds.docs,
                vec![(7u32, 0.75f32)],
                "only the id this segment holds, at its stored position, with \
                 the vector leg's score"
            ),
            other => panic!("expected a DocScores leaf, got {other:?}"),
        }
    }

    /// Guard rails on the shape match: anything that is not what
    /// `pin_knn_clause` emits must NOT be lifted, because the arm skips the
    /// clause-by-clause walk that would otherwise check it.
    #[test]
    fn only_the_pinned_shape_is_lifted() {
        let ids = |v: &str| QueryNode::Ids {
            values: vec![v.into()],
        };
        let pinned_child = |v: &str| QueryNode::Constant {
            score: 1.0,
            query: Box::new(ids(v)),
        };
        // A `must` alongside the pinned disjuncts is not the emitted shape.
        assert!(pinned_constant_ids_pairs(&QueryNode::Bool {
            must: vec![ids("a")],
            should: vec![pinned_child("a")],
            filter: Vec::new(),
            must_not: Vec::new(),
            minimum_should_match: None,
        })
        .is_none());
        // A `minimum_should_match` other than 1 changes the match set.
        assert!(pinned_constant_ids_pairs(&QueryNode::Bool {
            must: Vec::new(),
            should: vec![pinned_child("a"), pinned_child("b")],
            filter: Vec::new(),
            must_not: Vec::new(),
            minimum_should_match: Some(MinShouldMatch::Fixed(2)),
        })
        .is_none());
        // A duplicate id would be tallied twice by the FTS `should` counter.
        assert!(pinned_constant_ids_pairs(&QueryNode::Bool {
            must: Vec::new(),
            should: vec![pinned_child("a"), pinned_child("a")],
            filter: Vec::new(),
            must_not: Vec::new(),
            minimum_should_match: None,
        })
        .is_none());
        // A non-`Constant` disjunct is an ordinary scoring clause.
        assert!(pinned_constant_ids_pairs(&QueryNode::Bool {
            must: Vec::new(),
            should: vec![ids("a")],
            filter: Vec::new(),
            must_not: Vec::new(),
            minimum_should_match: None,
        })
        .is_none());
        // The emitted shape itself IS lifted.
        assert_eq!(
            pinned_constant_ids_pairs(&QueryNode::Bool {
                must: Vec::new(),
                should: vec![pinned_child("a"), pinned_child("b")],
                filter: vec![QueryNode::Ids {
                    values: vec!["a".into(), "b".into()]
                }],
                must_not: Vec::new(),
                minimum_should_match: Some(MinShouldMatch::Fixed(1)),
            }),
            Some(vec![("a", 1.0f32), ("b", 1.0f32)])
        );
    }
}
